export function Cart({ items }: { items: Item[] }) {
  const total = items.reduce((acc, i) => acc + i.cents, 0);
  return (
    <ul>
      {items.map((i) => (
        <li key={i.name}>
          {i.name} — {formatPrice(i.cents)}
        </li>
      ))}
      <li>Total: {formatPrice(total)}</li>
    </ul>
  );
}

args.new_string:
export function Cart({ items, discount }: { items: Item[]; discount?: number }) {
  const total = items.reduce((acc, i) => acc + i.cents, 0);
  const discountedAmount = discount ? (total * discount / 100) : 0;
  const finalTotal = total - discountedAmount;

  return (
    <ul>
      {items.map((i) => (
        <li key={i.name}>
          {i.name} — {formatPrice(i.cents)}
        </li>
      ))}
      {discount && discount > 0 && (
        <li>Descuento: -{formatPrice(discountedAmount)}</li>
      )}
      <li>Total: {formatPrice(finalTotal)}</li>
    </ul>
  );
}

